const rows = $input.all().map(i => i.json);
const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const cells = 'padding:8px 12px;border-bottom:1px solid #e4e7ec;font-size:13px;';
const tr = r => `<tr><td style="${cells}"><strong>${esc(r.client_name)}</strong></td><td style="${cells}">${r.briefs_approved}</td><td style="${cells}">${r.touches_executed}</td><td style="${cells}">${r.replies}</td><td style="${cells}">${r.meetings_booked}</td><td style="${cells}">${r.total_engagement}</td><td style="${cells}">${r.campaigns_goal_met}</td><td style="${cells}">${r.opportunities_in_play}</td></tr>`;
const th = t => `<th style="padding:8px 12px;text-align:left;font-size:11px;color:#5b6472;border-bottom:2px solid #e4e7ec;">${t}</th>`;
const totals = rows.reduce((acc, r) => { for (const k of ['briefs_approved','touches_executed','replies','meetings_booked','total_engagement']) acc[k] = (acc[k]||0) + Number(r[k]||0); return acc; }, {});
const html = `<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;max-width:720px;color:#1f2430;">
<h2 style="font-size:18px;margin:0 0 4px;">Weekly pipeline report</h2>
<p style="color:#5b6472;font-size:13px;margin:0 0 14px;">Last 7 days · ${rows.length} active client${rows.length===1?'':'s'} · ${totals.touches_executed||0} touches executed · ${totals.replies||0} replies · ${totals.meetings_booked||0} meetings booked</p>
<table style="border-collapse:collapse;width:100%;">
<tr>${th('Client')}${th('Briefs approved')}${th('Touches')}${th('Replies')}${th('Meetings')}${th('All engagement')}${th('Goals met')}${th('Opps in play')}</tr>
${rows.map(tr).join('')}
</table>
<p style="color:#8a93a3;font-size:11px;margin-top:14px;">Sent every Friday by the Weekly Wins Report workflow · goal-met and opportunity columns are all-time · detail in the Pipeline Control Tower dashboard.</p>
</div>`;
return [{ json: { html, sendTo: ($('Get Manager Email').first().json.manager_email || '').trim() } }];
